// src/utils/highLevelFunces.ts
function consumer(fn, time = 100) {
  const tasks = [];
  let timer;
  const nextTask = () => {
    if (tasks.length === 0) return false;
    tasks.shift().call(null);
    return true;
  };
  return function(...args) {
    tasks.push(fn.bind(this, ...args));
    if (timer == null) {
      nextTask();
      timer = setInterval(() => {
        if (!nextTask()) {
          clearInterval(timer);
          timer = null;
        }
      }, time);
    }
  };
}

